def describe_json(value):
    if isinstance(value, dict):
        return {"kind": "object", "count": len(value), "keys": list(value)}
    if isinstance(value, list):
        return {"kind": "array", "count": len(value)}
    if value is None:
        return {"kind": "null", "value": None}
    if isinstance(value, bool):
        return {"kind": "boolean", "value": value}
    if isinstance(value, int):
        return {"kind": "integer", "value": value}
    if isinstance(value, float):
        return {"kind": "number", "value": value}
    if isinstance(value, str):
        raw = value.encode("utf-8")
        return {"kind": "string", "utf8_bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}
    raise TypeError("non-JSON type")
